        arrow(g, ox, oy, ox, oy - 70, new Color(0x6AD66A), 2f);
        arrow(g, ox, oy, ox - 45, oy + 35, new Color(0x5A9AFF), 2f);
        label(g, "X", ox + 82, oy + 4, new Color(0xFF6A6A));
        label(g, "Y", ox, oy - 78, new Color(0x6AD66A));
        label(g, "Z", ox - 55, oy + 48, new Color(0x5A9AFF));
        g.setColor(Theme.rgba(0x8197AD, 0.35));
        g.setStroke(new BasicStroke(1f));
        for (int i = 0; i <= 4; i++) {
            g.draw(new Line2D.Double(w * 0.5 + i * 30, h * 0.5, w * 0.5 + i * 30 - 40, h * 0.85));
            g.draw(new Line2D.Double(w * 0.5 - i * 10, h * 0.5 + i * 26, w * 0.5 + 120 - i * 10, h * 0.5 + i * 26));
        }
        label(g, "drag — вращение · колесо — масштаб · правый клик — меню", w / 2.0, h * 0.14, Theme.TEXT);
